from fastapi import APIRouter, HTTPException
from typing import List, Dict, Any
from database import get_db
from schemas import RecommendationSchema
from agents.coordinator import CoordinatorAgent

router = APIRouter(prefix="/api/recommendations", tags=["AI Recommendations"])
coordinator = CoordinatorAgent()

@router.get("", response_model=List[RecommendationSchema])
def list_recommendations():
    """Retrieve autonomous recommendations generated by the multi-agent coordinator."""
    with get_db() as conn:
        cursor = conn.cursor()
        cursor.execute("SELECT * FROM recommendations ORDER BY CASE priority WHEN 'Urgent' THEN 1 WHEN 'High' THEN 2 ELSE 3 END;")
        rows = cursor.fetchall()
    return rows

@router.post("/{rec_id}/approve")
def approve_recommendation(rec_id: str):
    """
    Human-in-the-loop explicit approval.
    Executes the recommendation (e.g. creating a validated purchase order).
    """
    try:
        res = coordinator.approve_recommendation(rec_id)
        return res
    except ValueError as e:
        raise HTTPException(status_code=404, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

@router.post("/{rec_id}/dismiss")
def dismiss_recommendation(rec_id: str):
    """Dismiss a pending recommendation without action."""
    return coordinator.dismiss_recommendation(rec_id)
